package api

import (
	"bytes"
	"context"
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"os"
	"reflect"
	"testing"

	"github.com/crewship-ai/crewship/internal/backup"
	"github.com/crewship-ai/crewship/internal/documents"
)

// The fixture is a schema-2 Yjs paragraph with two text children, abc + def,
// and a real relative-span anchor over both, generated by schema.mjs.
func TestPageAssetsAndDocumentSpansShareEncryptedForkAndGCRoot(t *testing.T) {
	h, _, _, workspace, user, page := artifactFixture(t)
	raw, err := os.ReadFile("testdata/documents-asset-union.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Snapshot string          `json:"snapshot"`
		Blocks   json.RawMessage `json:"blocks"`
		Anchor   json.RawMessage `json:"anchor"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatal(err)
	}
	snapshot, err := base64.StdEncoding.DecodeString(fixture.Snapshot)
	if err != nil {
		t.Fatal(err)
	}
	store := documents.New(h.db, documents.Options{})
	key := documents.Key{WorkspaceID: workspace, PageID: page}
	allow := func(context.Context, *sql.Tx) (string, error) { return "user:" + user, nil }
	state, err := store.Init(t.Context(), key, 2, snapshot, fixture.Blocks, allow)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.Comment(t.Context(), key, "asset-document-comment", "mixed-backup-comment", "Retained cross-child discussion", fixture.Anchor, state.HeadRev, &state.Generation, allow); err != nil {
		t.Fatal(err)
	}
	uploaded := uploadAsset(t, h, workspace, user, "report", "document-asset", pageAssetPNG(t))
	artifactExpect(t, uploaded, 201)
	asset := assetMeta(t, uploaded)
	runAttachmentGCPass(t.Context(), h.db, h.logger, h.artifactStoragePath)
	artifactExpect(t, getAsset(t, h, workspace, user, "report", asset.ID, true), 200)
	const passphrase = "synthetic-document-asset-fork-passphrase"
	bundle, err := backup.CreateBackup(t.Context(), h.db, backup.CreateOptions{Scope: backup.ScopeWorkspace, WorkspaceID: workspace, OutputDir: t.TempDir(), Passphrase: passphrase, Actor: backup.Actor{UserID: user, Role: "ADMIN"}, AttachmentRoot: h.artifactStoragePath})
	if err != nil {
		t.Fatal(err)
	}
	target := setupTestDB(t)
	root := storageDir(t)
	restored, err := backup.RestoreBackup(t.Context(), target, backup.RestoreOptions{Path: bundle.Path, Passphrase: passphrase, AsWorkspace: "document-asset-fork", Actor: backup.Actor{UserID: user, Role: "ADMIN"}, AttachmentRoot: root})
	if err != nil {
		t.Fatal(err)
	}
	var assetID, pageID, owner, expiry string
	var actualSnapshot, actualAnchor []byte
	var schema int
	if err := target.QueryRow(`SELECT a.id,a.page_id,p.owner_user_id,a.expires_at,d.snapshot,d.schema_version FROM page_assets a JOIN pages p ON p.id=a.page_id JOIN documents d ON d.page_id=p.id AND d.workspace_id=p.workspace_id WHERE p.workspace_id=?`, restored.RestoredWorkspaceID).Scan(&assetID, &pageID, &owner, &expiry, &actualSnapshot, &schema); err != nil {
		t.Fatal(err)
	}
	if assetID == asset.ID || pageID == page || expiry != asset.ExpiresAt || schema != 2 || !bytes.Equal(actualSnapshot, snapshot) {
		t.Fatal("fork lost independent identities, expiry or exact document snapshot")
	}
	var commentID string
	if err := target.QueryRow(`SELECT id,anchor_json FROM document_comments WHERE workspace_id=? AND page_id=?`, restored.RestoredWorkspaceID, pageID).Scan(&commentID, &actualAnchor); err != nil {
		t.Fatal(err)
	}
	var original, forked map[string]any
	if err := json.Unmarshal(fixture.Anchor, &original); err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(actualAnchor, &forked); err != nil {
		t.Fatal(err)
	}
	if commentID == original["id"] || forked["id"] != commentID {
		t.Fatal("fork did not remap the comment and repeated anchor identity together")
	}
	delete(original, "id")
	delete(forked, "id")
	if !reflect.DeepEqual(original, forked) {
		t.Fatal("fork changed relative cross-child span metadata")
	}
	fork := NewPageHandler(target, nil, newTestLogger())
	fork.artifactStoragePath = root
	download := getAsset(t, fork, restored.RestoredWorkspaceID, owner, "report", assetID, true)
	artifactExpect(t, download, 200)
	if attachmentDigest(download.Body.Bytes()) != asset.SHA256 {
		t.Fatal("fork asset blob changed")
	}
	execOrFatal(t, target, `DELETE FROM workspace_members WHERE workspace_id=? AND user_id=?`, restored.RestoredWorkspaceID, owner)
	artifactExpect(t, getAsset(t, fork, restored.RestoredWorkspaceID, owner, "report", assetID, true), 403)
}
